export const TEMPLATES_PAGE_SIZE = 50
// The list API rejects a longer search. Template names are no longer, so a pasted name still matches.
export const TEMPLATE_SEARCH_MAX_LENGTH = 400

// The server counts characters by code point, and a cut through an emoji would leave half a pair that cannot be encoded.
export function cutTemplateSearch(search: string): string {
    return Array.from(search).slice(0, TEMPLATE_SEARCH_MAX_LENGTH).join('')
}

function isFiltered({ search, created_by, tags, transactional }: MessagingTemplatesListParams): boolean {
    return !!search || created_by !== undefined || !!tags || !!transactional
}

export interface MessageTemplatesLogicProps {
    listKey?: string
}

export const messageTemplatesLogic = kea<messageTemplatesLogicType>([
    props({} as MessageTemplatesLogicProps),
    key(({ listKey }) => listKey ?? 'library'),
    path((key) => ['products', 'workflows', 'frontend', 'library', 'messageTemplatesLogic', key]),
    connect(() => ({
        values: [teamLogic, ['currentTeamIdStrict']],
    })),
    actions({
        setSearch: (search: string) => ({ search }),
        setCreatedByFilter: (createdBy: number | null) => ({ createdBy }),
        setTransactionalOnly: (transactionalOnly: boolean) => ({ transactionalOnly }),
        setTagsFilter: (tagsFilter: string[]) => ({ tagsFilter }),
        templateTagsSaved: (template: MessageTemplate) => ({ template }),
        templatesPageLoaded: (listParams: MessagingTemplatesListParams, hasMoreTemplates: boolean, count: number) => ({
            listParams,
            hasMoreTemplates,
            count,
        }),
        listInvalidated: true,
        loadMoreTemplates: true,
        loadMoreTemplatesSuccess: (templates: MessageTemplate[], hasMoreTemplates: boolean) => ({
            templates,
            hasMoreTemplates,
        }),
        loadMoreTemplatesFailure: true,
        templatesAdded: true,
    }),
    reducers({
        search: ['' as string, { setSearch: (_, { search }) => search }],
        createdByFilter: [null as number | null, { setCreatedByFilter: (_, { createdBy }) => createdBy }],
        transactionalOnly: [false, { setTransactionalOnly: (_, { transactionalOnly }) => transactionalOnly }],
        tagsFilter: [[] as string[], { setTagsFilter: (_, { tagsFilter }) => tagsFilter }],
        hasMoreTemplates: [
            false,
            {
                templatesPageLoaded: (_, { hasMoreTemplates }) => hasMoreTemplates,
                loadMoreTemplatesSuccess: (_, { hasMoreTemplates }) => hasMoreTemplates,
            },
        ],
        moreTemplatesLoading: [
            false,
            {
                loadMoreTemplates: () => true,
                loadMoreTemplatesSuccess: () => false,
                loadMoreTemplatesFailure: () => false,
                loadTemplates: () => false,
            },
        ],
        // The filters the shown list came from, so a filter change stops paging until its first page lands.
        loadedListParams: [
            null as MessagingTemplatesListParams | null,
            {
                templatesPageLoaded: (_, { listParams }) => listParams,
                listInvalidated: () => null,
                loadTemplatesFailure: () => null,
            },
        ],
        templatesReloadFailed: [
            false,
            { loadTemplates: () => false, loadTemplatesFailure: () => true, templatesPageLoaded: () => false },
        ],
        // A failed count shows the guide's template step as not done, rather than hiding the whole guide.
        templateCount: [
            null as number | null,
            {
                loadTemplateCountFailure: (state) => state ?? 0,
                // An unfiltered page counts every template, so it stands in for a count that failed or has not landed.
                templatesPageLoaded: (state, { listParams, count }) =>
                    !state && !isFiltered(listParams) ? (count ?? state) : state,
            },
        ],
        templates: [
            [] as MessageTemplate[],
            {
                templateTagsSaved: (state, { template }) =>
                    state.map((t: MessageTemplate) => (t.id === template.id ? template : t)),
                loadMoreTemplatesSuccess: (_, { templates }) => templates,
            },
        ],
    }),
    loaders(({ values, actions, cache }) => ({
        templates: [
            [] as MessageTemplate[],
            {
                loadTemplates: async (_: void, breakpoint) => {
                    const { listParams } = values
                    let page
                    // Counted here because another loader's success clears the shared loading flag mid-request.
                    cache.firstPagesInFlight = (cache.firstPagesInFlight ?? 0) + 1
                    try {
                        page = await api.messaging.getTemplates(listParams)
                    } catch (error) {
                        // A failure for outdated filters must not offer a retry over the current list.
                        breakpoint()
                        throw error
                    } finally {
                        cache.firstPagesInFlight -= 1
                    }
                    breakpoint()
                    actions.templatesPageLoaded(listParams, !!page.next, page.count)
                    // A page read before a delete landed still holds the deleted template.
                    const deleted: Set<string> = cache.deletedTemplateIds ?? new Set()
                    return page.results.filter((t: MessageTemplate) => !deleted.has(t.id))
                },
                deleteTemplate: async (template: MessageTemplate) => {
                    await deleteWithUndo({
                        endpoint: `environments/${values.currentTeamIdStrict}/messaging_templates`,
                        object: {
                            id: template.id,
                            name: template.name,
                        },
                        callback: (undo) => {
                            cache.deletedTemplateIds ??= new Set<string>()
                            if (!undo) {
                                cache.deletedTemplateIds.add(template.id)
                            } else {
                                cache.deletedTemplateIds.delete(template.id)
                                actions.loadTemplates()
                                actions.loadTemplateCount()
                            }
                        },
                    })
                    actions.loadTemplateCount()
                    return values.templates.filter((t: MessageTemplate) => t.id !== template.id)
                },
                createTemplate: async ({ template }: { template: Partial<MessageTemplate> }) => {
                    try {
                        await api.messaging.createTemplate(template)
                        lemonToast.success('Template created successfully')
                        actions.templatesAdded()
                        return values.templates
                    } catch {
                        lemonToast.error('Failed to create template')
                        return values.templates
                    }
                },
                updateTemplate: async ({
                    templateId,
                    template,
                }: {
                    templateId: string
                    template: Partial<MessageTemplate>
                }) => {
                    try {
                        const updatedTemplate = await api.messaging.updateTemplate(templateId, template)
                        lemonToast.success('Template updated successfully')
                        return values.templates.map((t: MessageTemplate) => (t.id === templateId ? updatedTemplate : t))
                    } catch {
                        lemonToast.error('Failed to update template')
                        return values.templates
                    }
                },
                duplicateTemplate: async (template: MessageTemplate) => {
                    try {
                        await api.messaging.createTemplate({
                            name: `${template.name} (copy)`,
                            description: template.description,
                            content: template.content,
                        })
                        lemonToast.success('Template duplicated successfully')
                        actions.templatesAdded()
                        return values.templates
                    } catch {
                        lemonToast.error('Failed to duplicate template')
                        return values.templates
                    }
                },
            },
        ],
        templateCount: [
            null as number | null,
            {
                loadTemplateCount: async (_: void, breakpoint) => {
                    const page = await api.messaging.getTemplates({ basic: true, limit: 1 })
                    breakpoint()
                    return page.count
                },
            },
        ],
    })),
    selectors({
        listParams: [
            (s) => [s.search, s.createdByFilter, s.tagsFilter, s.transactionalOnly],
            (
                search: string,
                createdByFilter: number | null,
                tagsFilter: string[],
                transactionalOnly: boolean
            ): MessagingTemplatesListParams => ({
                limit: TEMPLATES_PAGE_SIZE,
                search: cutTemplateSearch(search.trim()) || undefined,
                created_by: createdByFilter ?? undefined,
                tags: tagsFilter.length ? tagsFilter : undefined,
                transactional: transactionalOnly || undefined,
            }),
        ],
        hasActiveFilters: [
            (s) => [s.listParams],
            (listParams: MessagingTemplatesListParams): boolean => isFiltered(listParams),
        ],
        // Paging stays off after a failed reload, so the list offers a first-page retry instead.
        canRetryTemplates: [
            (s) => [s.templatesReloadFailed, s.templatesLoading],
            (templatesReloadFailed: boolean, templatesLoading: boolean): boolean =>
                templatesReloadFailed && !templatesLoading,
        ],
        canLoadMoreTemplates: [
            (s) => [s.hasMoreTemplates, s.templatesLoading, s.loadedListParams, s.listParams],
            (
                hasMoreTemplates: boolean,
                templatesLoading: boolean,
                loadedListParams: MessagingTemplatesListParams | null,
                listParams: MessagingTemplatesListParams
            ): boolean => hasMoreTemplates && !templatesLoading && loadedListParams === listParams,
        ],
    }),
    listeners(({ actions, values, cache }) => ({
        setSearch: async (_, breakpoint) => {
            await breakpoint(300)
            actions.loadTemplates()
        },
        setCreatedByFilter: () => actions.loadTemplates(),
        setTagsFilter: () => actions.loadTemplates(),
        setTransactionalOnly: () => actions.loadTemplates(),
        templateTagsSaved: () => {
            // A tag edit can move a template out of a tag or search filter, and only the server knows.
            // A first page already in flight was read before the edit and would show the old tags.
            if (values.hasActiveFilters || cache.firstPagesInFlight > 0) {
                actions.listInvalidated()
            }
        },
        // Only the server knows whether a new template matches the filters and where it falls in the order.
        templatesAdded: () => {
            actions.loadTemplateCount()
            actions.listInvalidated()
        },
        // A create's own success clears the loading flag before this reload lands, so paging waits on the reload.
        listInvalidated: () => actions.loadTemplates(),
        loadTemplates: () => {
            cache.loadMoreRequest = (cache.loadMoreRequest ?? 0) + 1
        },
        loadMoreTemplates: async () => {
            const request = (cache.loadMoreRequest = (cache.loadMoreRequest ?? 0) + 1)
            const { listParams, templates, loadedListParams, templatesLoading } = values
            if (templatesLoading || loadedListParams !== listParams) {
                actions.loadMoreTemplatesFailure()
                return
            }
            try {
                const page = await api.messaging.getTemplates({ ...listParams, offset: templates.length })
                if (cache.loadMoreRequest !== request) {
                    return
                }
                // A reload or an edit that replaced the list leaves this page at the wrong offset.
                if (templates === values.templates && listParams === values.listParams) {
                    actions.loadMoreTemplatesSuccess([...templates, ...page.results], !!page.next)
                } else {
                    actions.loadMoreTemplatesFailure()
                }
            } catch {
                if (cache.loadMoreRequest === request) {
                    lemonToast.error('Failed to load more templates')
                    actions.loadMoreTemplatesFailure()
                }
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadTemplates()
        actions.loadTemplateCount()
    }),
])

// A plain function rather than a listener, because the caller awaits it to keep its editor open on
// a rejection, and a kea listener that rethrows raises an unhandled rejection on the way out.
export async function saveTemplateTags(template: MessageTemplate, tags: string[]): Promise<void> {
    const updated = await api.messaging.updateTemplate(template.id, { tags })
    messageTemplatesLogic.findMounted()?.actions.templateTagsSaved(updated)
}
